import { Stage } from "../Stage"

export default class extends Stage {
    protected *G(): Generator<void, void, unknown> {
        yield* this.wait(30)

        yield* this.text(`配給列の手伝いは、シオンにとって数少ない"仕事"だった。`)
        yield* this.text(`合成人の子供たちが、列の前方へ通される。<br>アオの決めた優先順位だった。`)

        yield* this.text(`「……また、あの子らが先か。」`, { name: "避難民の女" })
        yield* this.text(`「うちらだって、故郷追われてここに来てんのに。」`, { name: "避難民の女" })

        yield* this.text(`「後で融通するから。」`, { name: "テル" })
        yield* this.text(`「後で後でって、いつも後回しじゃないか。」`, { name: "避難民の女" })

        yield* this.text(`近くにいた土着派の男が、面白がるように口を挟んだ。`)
        yield* this.text(`「日本を取り戻す言うたら、あんたら畑違いやろ。<br>合成人優先て、逆差別もええとこや。」`, { name: "土着派の男" })

        yield* this.text(`列がざわつき始めたところへ、アオが割って入った。`)
        yield* this.text(`「誰も、後回しになんてしてない。<br>ここにいる全員が、生きる権利を持ってる。」`, { name: "アオ" })

        yield* this.text(`場の空気が、渋々ながら収まっていく。<br>アオの声には、いつもそういう力があった。`)

        yield* this.text(`シオンは、その横顔を眩しく見ていた。<br>ふと視線を外すと、列の奥から、こちらをじっと睨む合成人の女性と目が合った。`)
        yield* this.text(`睨んでいたのは、アオではなく、シオンの方だった。<br>名前も知らない顔だった。その時は、それだけのことだと思っていた。`)
    }
}
